-- Persistent panoramic read model and operating case coordination. / 持久全景读取及案件协同。
CREATE TABLE operating_snapshot(enterprise_id uuid NOT NULL,id text NOT NULL,checksum text NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(enterprise_id,id));
CREATE TABLE operating_review(enterprise_id uuid NOT NULL,id uuid NOT NULL,principal_id uuid NOT NULL REFERENCES principal(id),authorization_version integer NOT NULL,kind text NOT NULL CHECK(kind IN ('quality','store')),selection jsonb NOT NULL,request_key text NOT NULL,args_hash text NOT NULL,evidence_hash text NOT NULL,plan jsonb NOT NULL,state text NOT NULL CHECK(state IN ('waiting_approval','waiting_external','succeeded','partially_succeeded','waiting_input','cancelled')),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(enterprise_id,id),UNIQUE(enterprise_id,principal_id,request_key));
CREATE TABLE operating_assignment(enterprise_id uuid NOT NULL,id uuid NOT NULL,review_id uuid NOT NULL,ordinal integer NOT NULL,owner_role text NOT NULL,args jsonb NOT NULL,state text NOT NULL CHECK(state IN ('ready','dispatching','unknown','accepted','received','rejected','cancelled')),external_ref text,source_version integer,receipt jsonb,fence bigint NOT NULL DEFAULT 0,lease_until timestamptz,attempts integer NOT NULL DEFAULT 0,PRIMARY KEY(enterprise_id,id),UNIQUE(enterprise_id,review_id,ordinal),FOREIGN KEY(enterprise_id,review_id) REFERENCES operating_review(enterprise_id,id));
CREATE TABLE operating_review_event(enterprise_id uuid NOT NULL,review_id uuid NOT NULL,sequence integer NOT NULL,kind text NOT NULL,details jsonb NOT NULL,PRIMARY KEY(enterprise_id,review_id,sequence),FOREIGN KEY(enterprise_id,review_id) REFERENCES operating_review(enterprise_id,id));
ALTER TABLE operating_assignment ADD verification_attempts integer NOT NULL DEFAULT 0,ADD next_check_at timestamptz NOT NULL DEFAULT now(),ADD deadline timestamptz NOT NULL DEFAULT now()+interval '10 minutes',ADD manual boolean NOT NULL DEFAULT false;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['operating_snapshot','operating_review','operating_assignment','operating_review_event'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY enterprise_isolation ON %I USING(enterprise_id::text=current_setting(''app.enterprise_id'',true)) WITH CHECK(enterprise_id::text=current_setting(''app.enterprise_id'',true))',t);
 EXECUTE format('GRANT SELECT,INSERT,UPDATE ON %I TO eb_app',t);END LOOP;END $$;
REVOKE INSERT,UPDATE ON operating_snapshot FROM eb_app;
REVOKE UPDATE ON operating_review_event FROM eb_app;
CREATE FUNCTION guard_operating_review() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (NEW.principal_id,NEW.authorization_version,NEW.kind,NEW.selection,NEW.request_key,NEW.args_hash,NEW.evidence_hash,NEW.plan) IS DISTINCT FROM (OLD.principal_id,OLD.authorization_version,OLD.kind,OLD.selection,OLD.request_key,OLD.args_hash,OLD.evidence_hash,OLD.plan) THEN RAISE EXCEPTION 'review_content_immutable';END IF;
 IF OLD.state IN ('succeeded','partially_succeeded','cancelled') AND NEW.state<>OLD.state THEN RAISE EXCEPTION 'review_terminal_immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER operating_review_guard BEFORE UPDATE ON operating_review FOR EACH ROW EXECUTE FUNCTION guard_operating_review();
CREATE FUNCTION guard_operating_assignment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (NEW.review_id,NEW.ordinal,NEW.owner_role,NEW.args) IS DISTINCT FROM (OLD.review_id,OLD.ordinal,OLD.owner_role,OLD.args) THEN RAISE EXCEPTION 'assignment_content_immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER operating_assignment_guard BEFORE UPDATE ON operating_assignment FOR EACH ROW EXECUTE FUNCTION guard_operating_assignment();
